// ---- helpers (shared by the workflows in this pack) ----
const cfg = $('Config').first().json;
const zone = cfg.timezone || 'UTC';
const now = DateTime.now().setZone(zone);
const today = now.startOf('day');

// Read the first non-empty value among several possible column names.
const val = (row, ...keys) => {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

// Accepts 2026-11-20, 2026-11-20T14:30, 11/20/2026, 20.11.2026, Nov 20, 2026 or a Sheets serial number.
function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'utc' })
      .setZone(zone, { keepLocalTime: true });
  }
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone });
  if (d.isValid) return d;
  d = DateTime.fromSQL(s, { zone });
  if (d.isValid) return d;
  for (const f of ['M/d/yyyy', 'M/d/yyyy H:mm', 'M/d/yyyy h:mm a', 'M/d/yy', 'd.M.yyyy', 'yyyy/M/d', 'd MMM yyyy', 'MMM d, yyyy', 'MMMM d, yyyy']) {
    d = DateTime.fromFormat(s, f, { zone });
    if (d.isValid) return d;
  }
  const js = new Date(s);
  return isNaN(js) ? null : DateTime.fromJSDate(js).setZone(zone);
}

// Whole days between a date and today (positive = in the past).
const daysAgo = (d) => Math.round(today.diff(d.startOf('day'), 'days').days);

const firstName = (name) => (String(name || '').trim().split(/\s+/)[0] || 'there');

const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};

function money(amount, currency) {
  const cur = (currency || cfg.currency || 'USD').toUpperCase();
  try {
    return new Intl.NumberFormat(cfg.locale || 'en-US', { style: 'currency', currency: cur }).format(toNumber(amount));
  } catch (e) {
    return cur + ' ' + toNumber(amount).toFixed(2);
  }
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const button = (url, label) => url
  ? `<p style="margin:24px 0"><a href="${esc(url)}" style="background:${cfg.brandColor || '#2563eb'};color:#ffffff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block">${esc(label)}</a></p>`
  : '';

// Wraps body HTML in a clean, mobile-friendly email layout.
const layout = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1f2937;max-width:560px;margin:0 auto;padding:24px">${inner}<p style="margin-top:32px;color:#6b7280;font-size:13px">${esc(cfg.businessName || '')}</p></div>`;
// ---- end helpers ----

// Compares last week (Mon–Sun) with the week before.
const lastWeekStart = today.startOf('week').minus({ weeks: 1 });
const prevWeekStart = lastWeekStart.minus({ weeks: 1 });
const inRange = (d, start) => d && d >= start && d < start.plus({ weeks: 1 });

const leads = $('Get Leads').all().map((i) => i.json).map((r) => ({ d: parseDate(r['Date']), source: val(r, 'Source') || 'Unknown', status: val(r, 'Status').toLowerCase() })).filter((l) => l.d);
const sales = $('Get Sales').all().map((i) => i.json).map((r) => ({ d: parseDate(r['Date']), amount: toNumber(r['Amount']), who: val(r, 'Customer Name', 'Customer Email') || 'Customer' })).filter((s) => s.d);

const L1 = leads.filter((l) => inRange(l.d, lastWeekStart)), L0 = leads.filter((l) => inRange(l.d, prevWeekStart));
const S1 = sales.filter((s) => inRange(s.d, lastWeekStart)), S0 = sales.filter((s) => inRange(s.d, prevWeekStart));
const sum = (a) => a.reduce((t, s) => t + s.amount, 0);
const rev1 = sum(S1), rev0 = sum(S0);
const change = (a, b) => (b ? Math.round(((a - b) / b) * 100) : null);
const badge = (p) => (p === null ? '<span style="color:#6b7280">new</span>' : p >= 0 ? `<span style="color:#16a34a">▲ ${p}%</span>` : `<span style="color:#dc2626">▼ ${Math.abs(p)}%</span>`);

const countBy = (arr, key) => Object.entries(arr.reduce((m, x) => ((m[key(x)] = (m[key(x)] || 0) + 1), m), {})).sort((a, b) => b[1] - a[1]);
const sources = countBy(L1, (l) => l.source).slice(0, 5);
const byDay = Object.entries(S1.reduce((m, s) => ((m[s.d.toFormat('cccc')] = (m[s.d.toFormat('cccc')] || 0) + s.amount), m), {})).sort((a, b) => b[1] - a[1]);
const topCustomers = Object.entries(S1.reduce((m, s) => ((m[s.who] = (m[s.who] || 0) + s.amount), m), {})).sort((a, b) => b[1] - a[1]).slice(0, 5);

const row = (label, now_, prev, p) => `<tr><td style="padding:8px;border-bottom:1px solid #f3f4f6">${label}</td><td style="padding:8px;border-bottom:1px solid #f3f4f6;text-align:right"><b>${now_}</b></td><td style="padding:8px;border-bottom:1px solid #f3f4f6;text-align:right;color:#6b7280">${prev}</td><td style="padding:8px;border-bottom:1px solid #f3f4f6;text-align:right">${badge(p)}</td></tr>`;
const list = (pairs, fmt) => pairs.length ? '<ul>' + pairs.map(([k, v]) => `<li>${esc(k)}: <b>${fmt(v)}</b></li>`).join('') + '</ul>' : '<p style="color:#6b7280">No data</p>';
const conv = (s, l) => (l.length ? Math.round((s.length / l.length) * 100) + '%' : '—');

const html = layout(`
  <h2 style="margin:0">Weekly report</h2>
  <p style="margin:4px 0 16px;color:#6b7280">${lastWeekStart.toFormat('d LLL')} – ${lastWeekStart.plus({ days: 6 }).toFormat('d LLL yyyy')} vs the week before</p>
  <table style="width:100%;border-collapse:collapse;font-size:14px">
    <tr><th align="left">Metric</th><th align="right">Last week</th><th align="right">Week before</th><th align="right">Change</th></tr>
    ${row('Revenue', money(rev1), money(rev0), change(rev1, rev0))}
    ${row('Orders', S1.length, S0.length, change(S1.length, S0.length))}
    ${row('Average order', money(S1.length ? rev1 / S1.length : 0), money(S0.length ? rev0 / S0.length : 0), change(S1.length ? rev1 / S1.length : 0, S0.length ? rev0 / S0.length : 0))}
    ${row('New leads', L1.length, L0.length, change(L1.length, L0.length))}
    ${row('Orders per lead', conv(S1, L1), conv(S0, L0), null).replace('<span style="color:#6b7280">new</span>', '')}
  </table>
  <h3>Where leads came from</h3>${list(sources, (v) => v)}
  <h3>Best days</h3>${list(byDay.slice(0, 3), money)}
  <h3>Top customers</h3>${list(topCustomers, money)}
`);
return [{ json: { subject: `${cfg.businessName} weekly report: ${money(rev1)} revenue, ${L1.length} new leads`, html } }];
